REFS = {"1078154098564425938": "हॉट चॉकलेट बेल्जियम के मानकों पर बनी है फलों का जूस महंगा है लेकिन बहुत अच्छा है", "10590937942465254187": "गंभीर मौसम किसी भी खतरनाक मौसमी घटना के लिए वर्गीय शब्द है जिसमें नुकसान गंभीर सामाजिक व्यवधान या मानव जीवन की हानि की संभावना है", "10359991159058879218": "ms बीमारी केंद्रीय तंत्रिका तंत्र पर असर करती है जिसमें दिमाग स्पाइनल कॉर्ड और ऑप्टिक नर्व शामिल हैं", "10582204498174558997": "एक पूरी तरह से विकसित एथलीट की तरह बाघ चढ़ाई कर सकता है हालाँकि अच्छी तरह से नहीं तैर सकता है बड़ी दूरी तक छलांग लगा सकता है और एक शक्तिशाली मनुष्य के पाँच गुना बल के साथ खींच सकता है", "10245365873747218908": "यह संबंधित है लेकिन आम तौर पर इसमें अल्पाइन शैली की स्की टूरिंग या माउंटेनीयरिंग शामिल नहीं होती है जिसे खड़े इलाकों में किया जाता है और जिसके लिए बहुत कड़ी स्की और बूट की ज़रूरत होती है", "11014623647783711221": "इंटरनेट लोगों और अंतर-परस्पर संचार दोनों के तत्वों को मिलाता है", "10907654079731428081": "यदि आप केवल शिपबोर्ड भ्रमण का उपयोग करके किनारे तक जाते हैं तो आपको एक अलग वीज़ा की आवश्यकता नहीं होगी 2009 तक", "10014385262415025488": "ग्रीनलैंड को बहुत कम जगह बसाया गया था नॉर्स सगास में वे कहते हैं कि एरिक रेड हत्या के लिए आइसलैंड से निर्वासित किया गया था और आगे पश्चिम की यात्रा करते समय ग्रीनलैंड मिला जिसे ग्रीनलैंड नाम दिया गया", "10107687492910459268": "अपनी सरकार के अलावा आप अन्य देशों की सरकारों की सलाह ले सकते हैं हालांकि उनकी सलाह उनके नागरिकों को ध्यान में रखकर दी जाती हैं", "10128382631186456345": "प्राचीनकाल से ही लोग सोने चांदी और तांबे जैसे रासायनिक तत्वों के बारे में ही जानकारी रखते हैं क्योंकि इन्हें प्रकृति में मूल स्वरूप में ढूंढा जा सकता है और इन्हें प्राथमिक उपकरणों के ज़रिए ढूंढना अपेक्षाकृत आसान है", "10069289676238419279": "इंटरनेट पर यह खोज शत्रुतापूर्ण पर्यावरण पाठ्यक्रम के लिए अक्सर आपको एक स्थानीय कंपनी का पता प्रदान करेगी", "10135688561274120767": "इसे केमिकल का ph कहा जाता है आप लाल गोभी के जूस का इस्तेमाल करके एक संकेतक बना सकते हैं", "10921902647446458507": "यहूदी और गैर-यहूदी की तरह अभी भी ऐसे कई पुरुष और महिलाएं जीवित हैं जो उस समय बचने में सफल रहे और कई जिनके प्रियजनों को मार दिया गया या उनके मरने तक उनसे काम करवाया गया", "10550791631951016124": "हर कोई समाज से जुड़ा होता है और ट्रांसपोर्ट सिस्टम का उपयोग करता है लगभग सभी लोग ट्रांसपोर्ट सिस्टम के बारे में शिकायत करते हैं", "10015817292782645020": "ऐसी कोई वैश्विक परिभाषा नहीं है जिसके लिए निर्मित सामान एंटीक होते हैं कुछ कर एजेंसियां 100 साल से पुराने सामान को एंटीक के तौर पर परिभाषित करती हैं", "11063307654961399321": "केवल दो हफ़्तों में अमेरिकियों और फ़्री फ़्रेंच बलों ने दक्षिणी फ़्रांस को मुक्त कर दिया था और जर्मनी की ओर बढ़ रहे थे", "10291152526359423424": "केवल दो हफ़्तों में अमेरिकियों और फ़्री फ़्रेंच बलों ने दक्षिणी फ़्रांस को मुक्त कर दिया था और जर्मनी की ओर बढ़ रहे थे", "10286778291956788434": "पुरुषों के स्टैंडिंग सुपर-जी में ऑस्ट्रेलिया के मिशेल गौरले ग्यारहवें स्थान पर रहे चेक प्रतियोगी ओल्डरिच जेलिनेक पुरुषों के सिटिंग सुपर-जी में सोलहवें स्थान पर रहे", "10761312360331088376": "कैल्शियम और पोटैशियम जैसे तत्वों को धातु माना जाता है बेशक चांदी और सोने जैसी धातुएं भी हैं", "10622951485514869484": "हालांकि यह अकेला नहीं है प्रयोग करना और प्रयोग एक ऐसा परीक्षण होता है जिसका इस्तेमाल करके एक या इससे ज़्यादा संभावित परिकल्पनाओं को ख़त्म करने सवाल करने और अवलोकन करने से भी वैज्ञानिक शोध को मार्गदर्शन मिलता है", "10200643191519059428": "सबसे नज़दीकी सिरे पर क्रस्ट की मोटाई करीब 70 किलोमीटर है और सबसे दूर के सिरे पर यह 100 किलोमीटर है", "10798430940133763019": "जिस समय घटनाएँ हुई उसके युग को सामान्य रूप से यूरोप के इतिहास में 11वीं 12वीं और 13वीं सदी ad 1000-1300 में यूरोपियन इतिहास के उच्च मध्य युग की अवधि के रूप में बताया जाता है", "10972260827293009900": "लोग यह अनुमान नहीं लगा सकते हैं कि घर लौटने वाले यात्रियों के लिए धैर्य और समझ भी आवश्यक है", "11044357197343438539": "तकनीकी निर्धारण की ज़्यादातर व्याख्याएं दो सामान्य विचारों के बारे में बताती हैं तकनीकी विकास पर सांस्कृतिक या राजनीतिक असर का कोई भी प्रभाव नहीं पड़ता है और परिणामस्वरूप सामाजिक रूप से अनुकूलित होने के बजाय वह तकनीक निहित समाजों को प्रभावित करती है", "10027305580492162464": "टेलीविजन रिपोर्टों में प्लांट से निकलने वाला सफेद धुआं दिखाया गया है", "10011266027513218401": "कुछ अणुओं में अस्थिर केंद्रक होता है जिसका मतलब यह है कि उनमें थोड़े या बिना किसी झटके से टूटने की प्रवृत्ति होती है", "10980788482676060439": "उन्होंने अफवाहों को राजनीतिक बकवास और मूर्खतापूर्ण कहा", "10924000697500767031": "इटैलियन भी रोज़ाना इस्तेमाल होने वाली भाषा है जिसे राज्य में काम करने वाले अधिकांश लोग उपयोग में लाते हैं जबकि लेटिन का धार्मिक रस्मों में इस्तेमाल किया जाता है", "10587318592827006604": "विशेष रूप से सवाना पर बेहतरीन अफ़्रीकी वन्य जीवन को संपूर्ण रूप से देखने के लिए आमतौर पर सफ़ारी शब्द का उपयोग किया जाता है", "10847487616323903195": "कुछ लोगों ये सोचते थे की कि वह सही था लेकिन बहुत से लोग इसके विपरीत मानते थे; की सौर मंडल सूर्य और यहां तक कि अन्य सितारों सहित पृथ्वी के चारों और चक्कर लगता था ।"}
tr = jiwer.Compose([jiwer.ToLowerCase(), jiwer.RemovePunctuation(),
                    jiwer.RemoveMultipleSpaces(), jiwer.Strip(), jiwer.ReduceToListOfListOfWords()])
def strip_marks(w):
    w = unicodedata.normalize('NFC', w)
    return ''.join(ch for ch in unicodedata.normalize('NFD', w) if unicodedata.category(ch) != 'Mn')
DEV = lambda w: any('\u0900' <= c <= '\u097F' for c in w)
hasdig = lambda w: any(ch.isdigit() for ch in w)
def classify(r, h):
    if strip_marks(r) == strip_marks(h): return 'orthographic_variant'
    if hasdig(r) or hasdig(h): return 'number_form'
    if DEV(r) != DEV(h): return 'script_mismatch'
    return 'different_word'
hyps, reftexts, repl, n = [], [], 0, 0
for f in sorted(os.listdir(OUT)):
    if f.endswith('.json') and f[:-5] in REFS:
        raw = open(os.path.join(OUT, f), 'rb').read().decode('utf-8', errors='replace')
        repl += raw.count('\ufffd')
        d = json.loads(raw)
        hyps.append(' '.join(s['text'].strip() for s in d['transcription']))
        reftexts.append(REFS[f[:-5]]); n += 1
print('clips:', n)
m = jiwer.process_words(' '.join(reftexts), ' '.join(hyps), reference_transform=tr, hypothesis_transform=tr)
pairs, cats, ex = [], collections.Counter(), collections.defaultdict(list)
refw, hypw = m.references[0], m.hypotheses[0]
for a in m.alignments[0]:
    if a.type != 'substitute': continue
    rs = refw[a.ref_start_idx:a.ref_end_idx]; hs = hypw[a.hyp_start_idx:a.hyp_end_idx]
    for i in range(max(len(rs), len(hs))):
        r = rs[i] if i < len(rs) else None; h = hs[i] if i < len(hs) else None
        if r is None or h is None: continue
        c = classify(r, h); cats[c] += 1
        pairs.append({'ref': r, 'hyp': h, 'class': c})
        if len(ex[c]) < 4: ex[c].append([r, h])
out = {'model': 'ggml-medium.bin', 'lang': (sys.argv[4] if len(sys.argv)>4 else 'auto'), 'clips': n,
       'wer': round(m.wer*100,1), 'hits': m.hits, 'subs': m.substitutions,
       'del': m.deletions, 'ins': m.insertions,
       'ref_words': m.hits+m.substitutions+m.deletions,
       'utf8_repl': repl, 'cats': dict(cats), 'examples': dict(ex)}
json.dump(out, open(SUMMARY,'w',encoding='utf-8'), ensure_ascii=False, indent=1)
json.dump({'pairs': pairs}, open(DUMP,'w',encoding='utf-8'), ensure_ascii=False, indent=1)
print(json.dumps(out, ensure_ascii=False))
